<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Banners</div><div class="page-header list-header"><div><div class="eyebrow">APP CONTENT</div><h1>Banner photos</h1><p>Manage promotional images and their display sequence.</p></div><Link :href="route('banners.create')" class="primary-button">＋ Add banner</Link></div><section v-if="banners.length" class="banner-list"><Link v-for="banner in banners" :key="banner.id" :href="route('banners.edit',banner.id)" class="banner-item"><div class="banner-position"><span>ORDER</span><strong>{{ banner.display_order }}</strong></div><div class="banner-photo"><img :src="banner.image" alt="Banner photo"/></div><div class="banner-info"><strong>Banner #{{ banner.id }}</strong><span>Added {{ formatDate(banner.created_at) }}</span></div><div class="banner-arrow">›</div></Link></section><section v-else class="listing-panel empty-state banner-empty"><div>▧</div><strong>No banners yet</strong><p>Upload your first photo to show it in the app.</p><Link :href="route('banners.create')" class="primary-button">Add first banner</Link></section><div class="api-note"><span>GET</span><code>/api/banners</code><p>Returns {{ banners.length }} banner{{ banners.length===1?'':'s' }} ordered by display order.</p></div></Layout></template>
<script setup>import{onMounted}from'vue';import{usePage}from'@inertiajs/vue3';import{useToast}from'vue-toastification';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';defineProps({banners:{type:Array,default:()=>[]}});const formatDate=d=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d)),page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
